style.css:
@-moz-document domain("discord.com") {
body, #app-mount {
    background: #ffd6ec !important;
  }

  [class*="sidebar"],
  [class*="guilds"],
  [class*="container"] {
    background: #ffc0e0 !important;
  }

  [class*="chatContent"],
  [class*="messagesWrapper"],
  [class*="chat"] {
    background: #ffe4f2 !important;
  }

  [class*="membersWrap"] {
    background: #ffcce5 !important;
  }

  [class*="title-"],
  [class*="container-"],
  [class*="header-"] {
    background: #ffb6d9 !important;
  }

  [class*="message-"],
  [class*="messageContent"] {
    background: #fff0f8 !important;
    border-radius: 12px !important;
    padding: 4px 8px !important;
  }

  [class*="markup"],
  [class*="username"],
  [class*="name"] {
    color: #ff1493 !important;
  }

  ::-webkit-scrollbar {
    width: 8px !important;
  }
  ::-webkit-scrollbar-thumb {
    background: #ff80bf !important;
    border-radius: 4px !important;
  }
  ::-webkit-scrollbar-track {
    background: #ffe6f2 !important;
  }
}
